let testDictStringKeyValuePlannedHelperReleasesCollisionPayloads ()=
 let* instrs=generate [release L.DictHeap (AST.TDict (AST.TString,AST.TString))] in require (List.exists (function S.Label label when Text.contains label "collision_payload_loop"->true|_->false) instrs) "Dict<string, string> planned helper did not emit a collision payload release loop"
